from datetime import date, timedelta

class Loyalty:
    def __init__(self) -> None:
        # Stores purchases per customer: list of (purchase_date, points, expiry_date?)
        # and redemptions per customer: list of (redeem_date, points)
        self._purchases: dict[str, list[tuple[date, int]]] = {}
        self._redemptions: dict[str, list[tuple[date, int]]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero.")
        points = int(amount)  # 1 point per unit currency (assumption)
        if customer not in self._purchases:
            self._purchases[customer] = []
        self._purchases[customer].append((day, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        earned = 0
        if customer in self._purchases:
            for purchase_day, points in self._purchases[customer]:
                if purchase_day + timedelta(days=14) <= day:
                    earned += points

        spent = 0
        if customer in self._redemptions:
            for redeem_day, points in self._redemptions[customer]:
                if redeem_day <= day:
                    spent += points

        return earned - spent

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0 or points % 100 != 0:
            raise ValueError("Points must be a positive multiple of 100.")
        available = self.balance(customer, day)
        if points > available:
            raise ValueError("Not enough available points to redeem.")
        if customer not in self._redemptions:
            self._redemptions[customer] = []
        self._redemptions[customer].append((day, points))
```

This implementation ensures:
- Purchases with non-positive amounts raise `ValueError`.
- Points from purchases become available 14 days after the purchase.
- `balance` calculates only points that have matured and subtracts points already redeemed by that day.
- Redemptions are validated for multiples of 100 and sufficient balance.

